import { DatabaseSync } from 'node:sqlite';
function main(): void {
  const db = new DatabaseSync(':memory:');
  db.exec('CREATE TABLE t (v INTEGER)');
  console.log(db.isTransaction);
  db.exec('BEGIN');
  console.log(db.isTransaction);
  db.prepare('INSERT INTO t VALUES (?)').run(1);
  db.exec('ROLLBACK');
  console.log(db.isTransaction, db.prepare('SELECT count(*) AS n FROM t').get().n);
  db.exec('BEGIN');
  db.prepare('INSERT INTO t VALUES (?)').run(2);
  db.exec('COMMIT');
  console.log(db.isTransaction, db.prepare('SELECT v FROM t').all().map((r: any) => r.v).join(','));
  db.close();
}
